# Returns index of target in sorted array arr, or -1 if not found.
def binary_search(arr: list[int], target: int) -> int:
    def _search(left: int, right: int) -> int:
        if left > right:
            return -1
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            return _search(mid + 1, right)
        else:
            return _search(left, mid - 1)
    return _search(0, len(arr) - 1)

def is_valid_parentheses(s: str) -> bool:
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

# Example: is_valid_parentheses("([{}])") -> True

