def topological_sort(edges):
    if not edges:
        return []
    adj = {}
    indeg = {}
    for u, v in edges:
        adj.setdefault(u, []).append(v)
        indeg[v] = indeg.get(v, 0) + 1
        indeg.setdefault(u, indeg.get(u, 0))
    queue = [n for n, d in indeg.items() if d == 0]
    result = []
    while queue:
        n = queue.pop()
        result.append(n)
        for m in adj.get(n, []):
            indeg[m] -= 1
            if indeg[m] == 0:
                queue.append(m)
    return result if len(result) == len(indeg) else None

