class _Node:
    __slots__ = ('key', 'val', 'prev', 'next')
    def __init__(self, key, val):
        self.key, self.val, self.prev, self.next = key, val, None, None

def lru_cache_getset(capacity):
    """Returns (get, set) for an LRU cache of given capacity."""
    head = _Node(0, 0)
    tail = _Node(0, 0)
    head.next, tail.prev = tail, head
    store = {}
    def _remove(n):
        n.prev.next, n.next.prev = n.next, n.prev
    def _add_front(n):
        n.next, n.prev = head.next, head
        head.next.prev, head.next = n, n
    def get(key):
        """Return value or None if absent."""
        if key not in store:
            return None
        n = store[key]
        _remove(n)
        _add_front(n)
        return n.val
    def set(key, val):
        """Insert or update key-value pair."""
        if key in store:
            _remove(store[key])
        n = _Node(key, val)
        store[key] = n
        _add_front(n)
        if len(store) > capacity:
            lru = tail.prev
            _remove(lru)
            del store[lru.key]
    return get, set

