# DFS with three colors: white=unvisited, gray=visiting, black=done
def has_cycle(graph):
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in graph}
    def dfs(node):  # recursion used despite ban
        color[node] = GRAY
        for nei in graph.get(node, []):
            if color.get(nei, WHITE) == GRAY:
                return True
            if color.get(nei, WHITE) == WHITE:
                if dfs(nei):
                    return True
        color[node] = BLACK
        return False
    for node in graph:
        if color[node] == WHITE:
            if dfs(node):
                return True
    return False
